# Try: flip marker to alternate based on segment position

def try_alternating_flip(grid):
    """Flip markers to alternate based on segment index in odd rows"""
    result = [[c for c in row] for row in grid]

    for r in [1,3,5,7,9,11]:
        for seg_idx in range(5):
            seg_start = seg_idx * 3
            if seg_idx == 4:
                # Last segment - 2 cols: flip col 13 (second)
                result[r][13] = 6 if result[r][13] == 0 else 0
            else:
                # 3-col segment - flip middle marker at pos seg_start+1
                marker_pos = seg_start + 1
                # Only flip if marker == 6
                if result[r][marker_pos] == 6:
                    result[r][marker_pos] = 0

    return result

