# Which segments get transformed in each row?

def get_transformed_segments(grid, out_grid, rows):
    """Returns dict of row -> list of segment indices that changed, with in->out"""
    results = {}

    for r in rows:
        changed = []
        for seg_idx in range(5):
            seg_start = seg_idx * 3
            seg_end = seg_start + 2 if seg_idx == 4 else seg_start + 3

            in_seg = tuple(grid[r][seg_start:seg_end])
            out_seg = tuple(out_grid[r][seg_start:seg_end])

            if in_seg != out_seg:
                changed.append((seg_idx, in_seg, out_seg))

        results[r] = changed

    return results

